  ('d1ab5f65-99cb-4820-8547-6527097a724e'::uuid, 'https://pensera.chefsnbytes.com/assets/frango_menu/fdb-020.avif', 'Vatapá')
)
SELECT p.nome AS produto,
       f.foto,
       CASE WHEN p.id IS NULL THEN 'produto nao existe mais'
            WHEN coalesce(p.foto_url, '') = '' THEN 'vai receber'
            ELSE 'ja tem foto (fica)' END AS situacao
FROM fotos f
LEFT JOIN est_produtos p ON p.id = f.produto_id
ORDER BY situacao DESC, f.foto, p.nome;

