  ('c1bbafdd-0212-4ede-ae96-c49a31e84893'::uuid, 'https://pensera.chefsnbytes.com/assets/frango_menu/fdb-020.avif', 'Vatapá'),
  ('d1ab5f65-99cb-4820-8547-6527097a724e'::uuid, 'https://pensera.chefsnbytes.com/assets/frango_menu/fdb-020.avif', 'Vatapá')
),
gravados AS (
  UPDATE est_produtos p
     SET foto_url = f.url
    FROM fotos f
   WHERE p.id = f.produto_id
     AND coalesce(p.foto_url, '') = ''
  RETURNING p.id
)
SELECT count(*) AS produtos_com_foto_nova FROM gravados;
